# hypothesis: A concrete property listed before the abstract base in the MRO satisfies the abstract property, so the leaf instantiates while the unfinished subclass is rejected.
from abc import ABC, abstractmethod
from typing import assert_type


class Base(ABC):
    @property
    @abstractmethod
    def size(self) -> int: ...

    @abstractmethod
    def label(self) -> str: ...


class Sized:
    @property
    def size(self) -> int:
        return 3


class Left(Sized, Base):
    def label(self) -> str:
        return 'left'


class Right(Base):
    pass


class Leaf(Left, Right):
    pass


def try_right() -> str:
    try:
        Right()  # expect-error: Right leaves size and label abstract
    except TypeError:
        return 'rejected'
    return 'accepted'


leaf = Leaf()
assert_type(leaf.size, int)
assert_type(leaf.label(), str)
assert leaf.size == 3
assert leaf.label() == 'left'
assert try_right() == 'rejected'
